// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 09 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd1959191": "Слесарь-сантехник ЖЭКа Афанасий Борщев, которого жильцы запросто зовут Афоня, — человек открытой и доброй души. Живет он, правда, бездумно и легко, но, может быть, именно потому бывает ему порой тоскливо. Тогда он наведывается в местную пивную, где есть у него друг Федул. Однажды на танцах он знакомится с милой и трогательной девушкой Катей, полюбившей Афоню. Но он избегает ее, так как сердце его пленила хозяйка квартиры 58, красавица Елена. Однако вскоре выясняется, что она замужем. Почувствовав себя одиноким и никому не нужным, он едет в деревню к тетке.",
 "f-wd60498064": "Более чем через год после тех событий журналист Эдди Брок пытается приспособиться к жизни в качестве хозяина инопланетного симбиота Венома, который наделяет его сверхчеловеческими способностями. Брок пытается возродить свою карьеру и берет интервью у серийного убийцы Клетуса Касади, который по воле случая становится хозяином Карнажа и сбегает из тюрьмы после неудавшейся казни.",
 "f-wd25431158": "Когда в его жизнь врывается  суперсолдат с убийственной миссией, Дэдпул вынужден задуматься о дружбе, семье и о том, что на самом деле значит быть героем, попутно надирая 50 оттенков задниц. Потому что иногда чтобы делать хорошие вещи, нужно использовать грязные приемчики.",
 "f-wd19569225": "Молодой Артур живёт на задворках Лондиниума вместе со своей бандой. Он и понятия не имел о своём королевском происхождении, пока однажды не взял в руки меч Эскалибур. Меч начинает менять Артура. В результате он присоединяется к сопротивлению и таинственной молодой девушке по имени Гвиневра. Ему предстоит научиться понимать магическое оружие, которым он овладел, столкнуться со своими собственными демонами и объединить народ в борьбе против диктатора Вортигерна, убившего его родителей и завладевшего короной.",
 "f-wd134983890": "Российский ракетный подводный крейсер специального назначения бесследно исчезает во время секретной миссии в Гренландском море. На его поиски отправляется экипаж под командованием Виктора Воронина, чей старший брат Александр Воронин командовал пропавшей субмариной. Перед моряками стоит задача: любыми силами найти подлодку и не допустить, чтобы новое сверхсекретное оружие попало в руки врага. В это же время из-за геологических исследований на полярной станции в северных водах пробуждается Кракен: гигантское чудовище, способное сливаться с подводной тьмой, обладающее интеллектом неизвестной природы. Именно с ним предстоит столкнуться морякам, разыскивающим пропавшую подводную лодку.",
 "f-wd80379": "Бильбо Бэггинс, готовящийся отметить 111-ый день рождения, пишет книгу о своих приключениях 60-летней давности и уходит в воспоминания. Рассказ начинается с того, как хоббит, ни разу не покидавший родные земли, поддаётся на уговоры своего старого приятеля Гэндальфа Серого, отправиться в путешествие с 13-ью гномами во главе с Торином Дубощитом, которые держат путь в Эребор, откуда их когда-то давно изгнал огнедышащий дракон Смауг. Параллельно с этим в развалинах крепости Дол-Гулдур появляется могущественный некромант, угрожающий всему Средиземью.",
 "f-wd212965": "Будущее. Деспотичное государство ежегодно устраивает показательные игры на выживание, за которыми в прямом эфире следит весь мир. Жребий участвовать в Играх выпадает юной Китнисс и тайно влюбленному в нее Питу. Они знакомы с детства, но теперь должны стать врагами. Ведь по нерушимому закону Голодных игр победить может только один из 24 участников. Судьям не важно кто выиграет, главное — зрелище. И на этот раз зрелище будет незабываемым.",
 "f-wd113371337": "Эдди и Веном вынуждены бежать, ведь теперь их преследует два мира, которые закручивают всё в одну паутину. Поэтому они должны принять судьбоносное решение, которое станет их последним танцем.",
 "f-wd132863": "Рыба-клоун Марлин живёт на Большом Барьерном рифе и после трагедии становится чрезмерно осторожным отцом. Когда его единственного сына Немо ловят люди и увозят далеко от дома, Марлин отправляется через весь океан на его поиски. По пути он встречает добродушную и забывчивую рыбку Дори, которая становится его спутницей в полном опасностей путешествии. Им предстоит столкнуться с акулами, медузами, морскими течениями и множеством других испытаний. Тем временем Немо, оказавшись в аквариуме стоматологической клиники, пытается найти способ вернуться к отцу и не теряет надежды на спасение.",
 "f-wd54893954": "Москва, 1930-е годы. Популярный драматург обвиняется в антисоветчине: спектакль по его пьесе отменяют, а самого его выгоняют из союза литераторов. В не самый лучший момент своей жизни он встречает глубоко несчастную в браке красавицу Маргариту и начинает новый роман, героями которого становятся люди из его окружения, в том числе — мистический персонаж Воланд, списанный со знакомого иностранца.",
 "f-wd20977110": "Фильм завершает невероятную историю семьи Скайуокеров, длящуюся уже более сорока лет, и обещает дать ответы на все загадки из предыдущих серий. Зрителя ожидают старые и новые герои, уникальные миры, увлекательные путешествия на край Галактики и грандиозный финал фантастической саги.",
 "f-wd24053265": "XXVI век. На планете Земля богачи живут в Небесном городе, беднота довольствуется жизнью в Нижнем городе, куда сбрасываются все отходы и мусор. Однажды в куче металлолома Нижнего города учёный находит части женщины-киборга и возвращает её к жизни. Придя в сознание, киборг обнаруживает, что из ее памяти стерто все, кроме боевых приемов. Теперь она должна обрести утерянные воспоминания и выяснить, кто её отправил на свалку.",
 "f-wd20026847": "Два брата-лузера решают наведаться в хранилища пары-тройки банков, которые много лет безбожно обкрадывают своих должников. Расследование дерзких ограблений с грубым почерком увенчает карьеру шерифа Маркуса. Но куда выведет это нехитрое дело?",
 "f-wd979231": "Два детектива расследуют убийство в одном из номеров парижской гостиницы. Тем временем в другом номере Франсуаза и Эмиль Шеналь пытаются выбить долги из Джима Фокс Варнера, тренера по боксу. Однако Джим задолжал не только им, но и мафии. Теперь все его надежды связаны с предстоящим боем, в котором участвует его ученик",
 "f-wd11618": "Нервный Генри, живущий в промышленном городке, состоящем из дыма, шума и теней, вынужден жениться на своей подруге, после того, как она заявляет, что беременна, и в итоге становится отцом маленького, не похожего на человека ребенка-мутанта. Теперь перед семьей встает проблема с выхаживанием этого чудовища…",
 "f-wd186587": "1193-ий год до нашей эры. Наследник престола Трои, Парис, украл прекрасную Елену - жену царя Спарты Менелая. За честь Менелая вступается его брат - царь Агамемнон. Его армия под предводительством сильного воина Ахиллеса подошла к Трое и взяла город в кровавую осаду, длившуюся долгих 10 лет. Два мира будут воевать за честь и власть. Тысячи умрут за славу. И за любовь нация сгорит дотла.",
 "f-wd65921361": "Когда смышлёный мышонок Джерри сломал музыкальный инструмент, принадлежащий настырному коту Тому, мечтающему стать великим пианистом, между ними начинается настоящая война. В скором времени Джерри удаётся пробраться в отель, в который недавно устроилась работать Кайла в качестве сотрудника отдела планирования мероприятий. По мере того, как в отеле ведётся подготовка к роскошной свадьбе, Кайла замечает неуловимого мышонка, а затем обращается за помощью к Тому, чтобы избавиться от Джерри.",
 "f-wd5901134": "Вооружившись удивительной способностью уменьшаться в размере, но обладать при этом большой силой, мошенник Скотт Лэнг должен стать героем и помочь своему наставнику, доктору Хэнку Пиму, сохранить в тайне существование костюма Человека-муравья от угроз нового поколения.",
 "f-wd30602709": "Священная Римская империя погружается в кровавый хаос, пока враждующие претенденты сражаются за опустевший трон. Отважный лидер наемников по имени Ян нехотя соглашается на коварный ход в политической игре: похитить невесту могущественного вельможи, чтобы преградить последнему путь к власти. Но неожиданно для себя Ян начинает испытывать сильные чувства к своей заложнице и, чтобы освободить ее, бросает вызов целой армии, стоящей на страже порочной аристократии. Герой понимает, что теперь судьба Империи, как, впрочем, и его любви, – не в руках королей, а только в его руках. И в своей беспощадной битве Ян пойдет до конца...",
 "f-wd951071": "Окружной прокурор пошёл на сделку с преступниками и освободил их из тюрьмы. Тогда человек, чья жена и ребёнок погибли от рук убийц решает отомстить прокурору, совершив правосудие самостоятельно. Его ловят и сажают в тюрьму, но он неожиданно ставит ультиматум: он будет убивать, не выходя из-за решетки, если его требования не будут выполнены. Смешное заявление, но вскоре люди правда начинают гибнуть...",
 "f-wd1405126": "В этом фильме на основе романа Брета Истона Эллиса бизнесмен, ведущий двойную жизнь серийного убийцы, пытается сохранить иллюзию благопристойности и собственный рассудок.",
 "f-wd84712809": "17-летний Билли Бэтсон, получивший дар превращаться в супергероя лет сорока, охраняет покой жителей Филадельфии вместе со своими приёмными братьями и сестрами, с которыми он поделился суперспособностями. В силу юности и недостатка дисциплины не всё у них получается идеально, и пресса называет команду супергероев \"Филадельфийскими фиаско\". Тем временем две женщины, представляющиеся дочерьми титана Атланта, крадут из греческого музея сломанный пополам волшебный жезл и направляются в Филадельфию, чтобы отобрать у супергероев магические силы.",
 "f-wd112977213": "2050-ые. Спасаясь от кровожадного кредитора, который расчленяет своих должников, Микки Барнс вместе с приятелем записывается в колонисты планеты Нифльхейм. Вот только друг становится пилотом, а сам Микки вынужден стать расходным сотрудником — выполнять смертельные задания, умирать и снова оживать в свеженапечатанном теле, в которое загружается его сознание. Упавшего в пещеру Микки 17 спасают обитающие на Нифльхейме ползуны, а вернувшись на базу, парень встречает свою 18-ую версию.",
 "f-wd130268157": "Между концертами на стадионах суперзвёзды кей-попа Руми, Мира и Зои защищают фанатов от сверхъестественных угроз с помощью своих тайных способностей.",
 "f-wd89474225": "Расследуя возникновение аномалии точки перехода, Кэрол Дэнверс и Моника Рамбо независимо друг от друга одновременно касаются её и тем самым спутывают свои силы с Камалой Хан. Теперь девушки меняются местами, когда кто-нибудь из них использует сверхспособности. А в это время предводительница кри с помощью одного из Квантовых наручей (точно такого же, какой достался Камале по наследству) пытается спасти свою планету от гибели, воруя ресурсы у других планет. Чтобы не допустить хаос, Кэрол, Монике и восторженной от грядущего приключения Камале предстоит научиться работать в команде.",
 "f-wd123169098": "В жизни Чака происходит нечто странное: мир вокруг постепенно рушится, а повсюду появляются загадочные послания со словами благодарности ему. Кто же такой Чак и почему он оказывается связан с судьбой целого мира? Оказывается, за внешней простотой его бытия скрываются глубокие переживания, радость, боль и удивительные открытия, которые делают эту жизнь по-настоящему невероятной.",
 "f-wd1127167": "Солнечный летний день 1936 года. Молодая страна, полная энтузиазма, празднует 4-ю годовщину сталинского дирижаблестроения. Легендарный комдив Котов и его большая шумная семья отдыхают на даче. В старом доме собралась тьма народу: жена-красавица, непоседа-дочь, тесть — известный русский дирижёр, родственники и друзья, домработницы и соседи. Веселье бьёт через край, и мысль, что что-то в жизни может измениться, покажется всем абсурдом. Они все будут счастливы вечно! И никто, даже мудрый Котов, не хочет верить в неизбежное. В то, что этот солнечный день кончится — и не повторится уже никогда.",
 "f-wd109511080": "Разведённая пара вынуждена объединиться, чтобы поехать на Бали и помешать дочери Лили выйти замуж за местного парня. По их мнению, девушка совершает ту же ошибку, что и они 25 лет назад...",
 "f-wd9653404": "Город нуждается в героях. Тьма окутала Нью-Йорк в виде Шреддера и его зловещего Клана Футов, у которого имеется железный контроль над всеми, от полицейских до политиков. Будущее выглядит мрачным, пока из канализации не поднимается и не раскрывает своё предназначение четвёрка отверженных братьев.",
 "f-wd122203155": "Сентябрь 1977 года. Мария Каллас, всемирно известная оперная дива на ранней пенсии, живет в роскошной парижской квартире с двумя пуделями, кухаркой и дворецким. Работа первой, помимо готовки, заключается в том, чтобы говорить Марии комплименты. Второй с утра до ночи передвигает для нее по дому огромный рояль, считает её таблетки, забирает её из ресторанов и пытается убедить побеседовать наконец не с галлюцинациями, а со специалистом.",
 "f-wd43051": "Однажды утром на маленькой, освещенной весенним солнцем, лесной полянке родился олененок. На нового лесного принца сбежались и слетелись посмотреть все звери и птицы. Олененка назвали Бемби. Когда Бемби научился ходить и разговаривать он обзавелся друзьями — кроликом Тампером и скунсом Цветочком. А однажды на лугу, куда привела его мама, Бемби познакомился с маленькой веселой оленихой — Фэйлин. Но жизнь в лесу бывает опасной и жестокой. Впервые Бемби столкнулся с этим, когда прозрачный осенний лесной воздух пронзили выстрелы из ружья — все звери начали в панике убегать, и тогда Бемби впервые услышал страшное слово — Человек.",
 "f-wd179503": "Ленивец Сид, бредя желанием создать собственное племя, решился приютить несколько найденных яиц, не подозревая кто в них находится. Но вскоре за ними пришла их мама и забрала Сида и детёнышей с собой. Отправившись на помощь, друзья попадают в таинственный мир, скрытый под толщами льда, где они сталкиваются с динозаврами и агрессивной окружающей средой, а так же знакомятся с охотником на динозавров — лаской по имени Бак. А Скрат по-прежнему гоняется за своим орехом.",
 "f-wd186323": "Телеведущий из Казахстана Борат отправляется в США, чтобы сделать репортаж об этой «величайшей в мире стране». Однако по прибытии оказалось, что главная цель его визита — поиски Памелы Андерсон с целью жениться на ней, а вовсе не съёмки документального фильма…",
 "f-wd193066": "Нью-Йорк — столица сильных мира сего и уютное гнёздышко очаровательной Холли Голайтли. Кто-то назовет её девицей по вызову, кто-то — авантюристкой. Одни подумают, что она хитра как лисица, другие решат, что тупа как пробка. Холли это безразлично. Она наслаждается жизнью, меняет наряды и ищет богатого жениха. Но однажды этажом выше селится симпатичный молодой человек.",
 "f-wd16857406": "Непримиримая борьба с опасным и внушающим страх тигром Шерханом вынуждает Маугли покинуть волчью стаю и отправиться в захватывающее путешествие. На пути мальчика ждут удивительные открытия и запоминающиеся встречи с пантерой Багирой, медведем Балу, питоном Каа и другими обитателями дремучих джунглей.",
 "f-wd213081": "Когда Нерон с планеты Ромул приходит из будущего, чтобы отомстить Федерации, конкуренты Кирк и Спок должны объединиться, чтобы не дать ему разрушить все, что им дорого. Во время этого будоражащего путешествия, наполненного эффектными боями, юмором и космическими угрозами, новоиспеченные члены команды военного корабля «Энтерпрайз» смело встретятся лицом к лицу с невообразимыми опасностями.",
 "f-wd207916": "Медиамагнат Элиот Карвер, один из самых влиятельных и богатых людей планеты. Он хочет присоединить Китай к своей глобальной телекоммуникационной империи. Китай как всегда не спешит с решением, и это выводит Карвера из равновесия. Для достижения своих целей он не остановится ни перед чем. А имея в распоряжении самый эффективный инструмент формирования общественного мнения, он готов даже спровоцировать третью мировую войну. Чтобы предотвратить катастрофу, Джеймсу Бонду необходимо использовать все свои необыкновенные способности, благо прогресс не стоит на месте, и Бонда вовремя снабжают новыми высокотехнологичными разработками из шпионских лабораторий.",
 "f-wd269912": "После окончания колледжа Эмори один из его ведущих студентов и атлетов Кристофер МакКэндлесс оставляет всё своё имущество, отдаёт накопленные за время учебы 24 тыс. долларов в благотворительный фонд, и отправляется автостопом на Аляску, чтобы окунуться в дикую природу. По дороге Кристофер знакомится с разными людьми, так или иначе влияющими на его жизнь.",
 "f-wd208131": "За всё время Шрэк пережил немало различных приключений и испытаний, и вот, наконец, он ведёт тихую и спокойную семейную жизнь. Однако в скором времени, он начинает всё чаще вспоминать о былых временах, когда его все боялись, и он делал всё что хотел. И вот однажды, доведённый повседневной рутиной до отчаяния, у Шрэка, прямо на дне рождения его детишек, случается приступ гнева, в результате чего он ссориться со всеми гостями и Фионой, после чего уходит. Блуждая по лесу, Шрэк встречает колдуна Румпельштильцхена, который предлагает ему заключить договор, благодаря которому он сможет вернуть свою старую жизнь. Вот только огр даже представить себе не мог, чем для него это всё обернётся.",
 "f-wd162277": "Спустя 40 лет после гибели Александра пожилой Птолемей, один из ближайших соратников Македонского, ставший после его смерти наместником Египта, решает рассказать и записать историю побед великого полководца. В течение восьми лет войско Александра Великого двигалось на Восток, к берегам мирового Океана.",
 "f-wd270385": "Англия, конец XVIII века. Родители пятерых сестер Беннет озабочены тем, чтобы удачно выдать дочерей замуж. И потому размеренная жизнь солидного семейства переворачивается вверх дном, когда по соседству появляется молодой джентльмен - мистер Бингли...\r Само собой, среди друзей нового соседа оказывается немало утонченных аристократов, которые не прочь поухаживать за очаровательными сестрами. Однако, все не так просто. Своевольная Элизабет знакомится с другом Бингли - красивым и высокомерным мистером Дарси, и между ними разгорается нешуточное противостояние, результатом которого может стать как любовь, так и ненависть...",
 "f-wd2937646": "В начале апреля 2009 года близ берегов Африки несколько сомалийских пиратов атакуют и пытаются захватить массивный контейнеровоз MV Maersk Alabama. Команда корабля активно сопротивляется и в не даёт взять себя в плен. Захватчики вынуждены ретироваться и покинуть судно на небольшом катере, прихватив с собой капитана Ричарда Филлипса.",
 "f-wd387601": "Молодой человек в поисках работы попадает в музей, где приступает к обязанностям ночного сторожа. Оказывается, не такая это простая работа, как могло показаться на первый взгляд. Ведь самое главное — не только не дать никому войти в музей, но и не позволить никому и ничему из музея выйти….",
 "f-wd221820": "2001 год. Менеджер бейсбольной команды Oakland Athletics Билли Бин после проигрыша в ключевом матче команде New York Yankees, которая обладает значительно большим бюджетом, решает в корне изменить систему подбора игроков. Во время деловой поездки в Кливленд он знакомится с молодым выпускником Йеля, экономистом Питером Брэндом, который при помощи математических расчётов предлагает внедрить новаторскую схему оценки полезности игроков, основываясь на показателях их личной статистики.",
 "f-wd387348": "Элвин и бурундуки, как это ни смешно, — настоящий бренд и легенда. Писклявое трио бурундуков и Дэйв Севиль за время своей музыкальной карьеры стали настоящей иконой. Более 43 миллионов проданных альбомов, несколько премий «Грэмми», популярный телевизионный анимационный сериал, рейтинговые субботние шоу. Их видели более чем в 100 странах мира, на более чем 40 языках. Теперь они пожалуют и к нам.",
 "f-wd329131": "Уволенный за критику начальства, спортивный агент Джерри Магуайер решает создать свою фирму. Лишь два человека верят в него — влюбленная в Магуайера Дороти и Род Тидвелл — талантливый спортсмен, но нахальный и крайне злобный тип.Но обстоятельства не останавливают Джерри — он уверен в себе и твердо знает, чего хочет. И все могло бы быть как нельзя лучше, если бы не его бывшие коллеги. Для них все методы хороши — особенно если нужно доказать правдолюбцу, кто правит бал. И Джерри Магуайер знает — если он проиграет, то встать на ноги ему не удастся никогда.",
 "f-wd741878": "Вьетнам 1965 года — пока еще безмятежный курорт с жарким солнцем, красивыми девушками и привольной службой. Но однажды утром раздался оглушительный взрыв… хохота, когда в эфир армейской радиостанции впервые вышел новый ведущий Эдриан Кронауэр.Он сразу стал любимцем публики и врагом высокого начальства. И действительно, этот юморист своими шутками и непредсказуемым поведением представляет настоящую угрозу для воинской дисциплины. Но когда в радиоприемниках раздается его знаменитое приветствие «Доброе утро, Вьетнам!», кажется, что в этой солнечной стране никогда не наступит ночь…",
 "f-wd276523": "Над Готэмом вновь нависла угроза: злодей-морозилка Мистер Фриз и психованная любительница растений по кличке Ядовитый Плющ решают уничтожить город. Единственные, кто могут остановить злодеев — Бэтмен и Робин, однако у этих супергероев возникают разногласия...",
 "f-wd308929": "Джейк Хойт устраивается на работу в отдел по борьбе с наркотиками полиции Лос-Анджелеса. Его напарником становится опытный полицейский Алонзо Харисс, который в борьбе с преступностью далеко не всегда использует законные методы. И почти сразу Джейк оказывается вовлечённым в стремительный водоворот событий.",
 "f-wd223217": "Главными героями мультфильма станут всеобщие любимцы Тимон и Пумба! Вы узнаете об этих закадычных друзьях много нового, например, о том, как они впервые встретились, что за потрясающие приключения вместе прожили и на какие удивительные подвиги их сподвигло знаменитое знакомство с будущем королем саванны Симбой. А также познакомитесь с новыми забавными героями, которые точно не дадут вам скучать — заботливой мамочкой Тимона и его ужасно саркастичным дядей Максом! Скучно не будет!",
 "f-wd48980": "Флетчер Рид - блестящий адвокат и неисправимый лжец. Он по привычке врёт жене Одри, сыну Максу и учит клиентов подстраивать правду под свои нужды, перекраивать истину ради своей выгоды. Жена бросает Флетчера из-за его вредной привычки лгать, а сын Макс в свой день рождения, задувая свечи на торте, загадывает только одно желание: «Хочу, чтоб мой любимый папочка перестал постоянно врать».",
 "f-wd28234": "Франция, начало XIX века. Беглый каторжник Жан Вальжан, приговорённый к тюремному заключению, вынужден долгие годы скрываться от жестокого правосудия. Инспектор парижской полиции Жавер считает его поимку делом всей своей жизни. После смерти Фантины — женщины, за судьбу которой Жан Вальжан считал себя в ответе, — единственным близким ему человеком остается её дочь Козетта. Ради счастья девушки Жан готов на все.",
 "f-wd220423": "Как-то зимним днем в тихом французском городке появляется молодая женщина по имени Виенн. А чуть позже она открывает необычный шоколадный магазин, предлагая посетителям испытать новое удовольствие. И действительно, побывав у нее однажды, люди вновь и вновь поддаются сладкому очарованию. Просто Виенн волшебным образом угадывает чужие желания. И они сбываются! Но только когда в город приезжает Ру, Виенн, наконец, смогла понять свои собственные…",
 "f-wd464964": "Героическая история диктатора, который рискует своей жизнью, чтобы ни в коем случае не допустить демократию в свою столь любовно угнетаемую страну.",
 "f-wd504053": "Гангстер Денни Оушен собрал свою банду профессиональных грабителей и мошенников, и теперь там появились новые лица. Они задумали совершить три ограбления в европейских столицах. Владелец казино Терри Бенедикт, которого Оушен ограбил в Лас-Вегасе, жаждет мести и пытается настигнуть банду. За ней также охотятся агенты Европола и Диннер Джекет.",
 "f-wd596623": "В мае 1860 года в Италии разгорается гражданская война между республиканцами, сторонниками Гарибальди, и приверженцами правящей династии Бурбонов. Князь Фабрицио ди Салина, сицилийский феодал, образованный и мудрый аристократ-интеллектуал, с пониманием и пессимизмом относится к происходящим переменам.  Поэтому, когда его молодой племянник Танкреди сначала вступает в ряды мятежников-гарибальдийцев, а затем становится офицером короля Савойского, дон Фабрицио не осуждает его. Сам князь Салина не хочет активно участвовать в политической борьбе. Он прекрасно осознает неизбежность происходящих больших перемен и чувствует, что его время «леопардов» и «львов» — уходит.  «Я принадлежу к уходящему классу, я свободен от иллюзий и не способен к самообману, — говорит он. Мы — леопарды, львы. Те, кто придет на смену, будут шакалишками, гиенами».",
 "f-wd45839": "Маленькую прелестную девочку из бедной японской семьи отдают в услужение в дом гейш. С годами красавица расцветает и познает все таинства этой профессии. Самые влиятельные мужчины становятся пленниками знаменитой гейши по имени Сайюри, достигшей совершенства в своем искусстве.Но в сердце Сайюри теплится любовь к тому, над которым ее чары не властны. Тайну своей любовной страсти она доверяет лишь страницам дневника…",
 "f-wd637021": "Двенадцатилетняя Лира отправляется в удивительное путешествие к Северному Полюсу, чтобы спасти своего похищенного друга. В помощь к девочке приходят северные ведьмы под предводительством прекрасной Серафины Пеккала и огромный бронированный медведь. На пути их стоят зловещая Миссис Коултер и армия её монстров.",
 "f-wd83767": "Страшное кораблекрушение, счастливое спасение и необитаемый остров положили начало одной из самых красивых и трогательных историй о любви. Долгие годы юная пара живет на прекрасном тропическом острове. Но по мере того, как они взрослеют, в их сердцах зарождается возвышенная, красивая, как окружающий мир, любовь.",
 "f-wd830208": "История начинается непосредственно с того момента, на котором закончилась первая часть — полицейские Ли и Картер прибывают в Гонконг по следам преступников, замышляющих похищение китайский сокровищ и продажи их в штатах. По мере того, как детективы Картер и Ли становятся все больше и больше запутанными в преступном заговоре, вовлекающем их в смертоносную Триаду, поездка в стиле нон-стоп от Гонконга до Лос-Анджелеса и Лас-Вегаса, оборачивается для них безумно интересным, смешным и в то же время опасным приключением.",
 "f-wd1304993": "Фильм рассказывает о русском солдате, которого война подвергла страшным испытаниям, лишила дома и семьи, бросила в концлагерь. Но судьба не сломила его дух - он выжил, отстоял своё право быть человеком, сохранил способность любить...",
 "f-wd1304344": "После долгой, напряженной работы, когда все запасы продовольствия были уже на исходе, наступали первые осенние холода и не оставалось никаких надежд, были найдены, наконец, алмазы. Но утром разметался по тайге пожар и отрезал геологам путь к лодкам с продовольствием и снаряжением. Их было четверо в пылающей тайге. И геологам надо было не только спасти друг друга, но и передать знания о найденных алмазах на Большую Землю…",
 "f-wd2493669": "Лето 1944 года, Красная Армия ведет бои на подступах к западной границе СССР. В тыл врага отправляется группа разведчиков, молодых ребят. Их позывные - «Звезда». Они должны выполнить задание, от которого зависит судьба фронта. И они выполняют его, но цена этого задания оказывается слишком дорогой. Полный напряжения и драматизма, фильм заставляет вспомнить, кто победил в этой войне.",
 "f-wd2723465": "Пожилая женщина Александра приезжает в военную часть навестить внука, офицера Российской Армии, служащего в Чечне. Туда, где только-только отгремела война. Она чужая в этом царстве молодых и сильных мужчин, но Александра приехала сюда не просто на свидание. Ее волнует не только собственный внук, молодой офицер, живущий только войной.  Александра пытается понять этот «раненый» город, людей в нем. Ее чувства - гораздо сильнее пушек и танков. Надежда и вера, про которые все окружающие уже успели забыть. Она не может изменить мир, но может излечить души людей, вернуть их к жизни и подарить хоть каплю доброты и сострадания. Ко всем. Таким близким и таким чужим, но все же… людям.",
 "f-wd4189193": "Середина 30-х годов. Демобилизованный танкист-дальневосточник Клим Ярко возвращается в украинский колхоз, где живет давно полюбившаяся ему Марьяна Бажан. Но Марьяна — уже прославленная трактористка района и у нее много поклонников, от которых она мечтает избавиться, выдумав любовь к силачу и лодырю Назару. В сложную ситуацию попадает простодушный Клим, но, в конце концов, искренностью и трудолюбием завоевывает симпатии всего колхоза и любовь знаменитой Марьяны.",
 "f-wd400218": "Ресторан «Одуванчик» пользовался дурной славой. В нем было грязно, готовили мерзко, персонал норовил нахамить. Журналисту Никитину и его друзьям удается помочь директору ресторана превратить «Одуванчик» в образцовое молодежное кафе...",
 "f-wd2036372": "Мультипликационный фильм по мотивам повести С. Лагерлеф «Чудесное путешествие Нильса с дикими гусями». Сказочная история рассказывает об озорнике Нильсе, который обидел волшебного Гнома, за что был наказан: превращен в карлика и унесён гусями в Лапландию. Много благородных поступков совершил мальчик, прежде чем Гном снял с него чары.",
 "f-wd1219413": "Задумал отец женить трёх своих сыновей. Вышли братья в чистое поле и пустили стрелы в разные стороны. Стрела старшего сына упала на боярский двор, к боярской дочери, стрела среднего сына — упала на двор купеческий, а стрела Ивана, младшего сына, упала на болото к лягушке-квакушке…",
 "f-wd617144": "Выпускник школы Иван, дожидаясь призыва в армию, работает курьером в редакции. Окружающие его солидные взрослые люди с трудом приспосабливаются к удивительной способности этого парня любое событие превратить в невероятное происшествие - порой уморительно веселое, а, подчас, и непоправимо грустное.",
 "f-wd3547387": "«Великий комбинатор» Остап Бендер с детства мечтает о Рио-де-Жанейро. Ему известны множество способов «сравнительно честного отъема денег у граждан». Но - где же в Советской России найти гражданина, обладающего хотя бы полумиллионом рублей? И вот подпольный миллионер, выдающий себя за скромного служащего на нищенском жалованье, найден. И должен сам принести деньги Остапу «на блюдечке с голубой каемочкой». Как же великий комбинатор добьется этого? Сбудется ли мечта его детства?",
 "f-wd4083026": "Петербург 40-х годов XIX столетия. Лето, белые ночи. На берегу Невы Мечтатель знакомится с Настенькой. Пять ночей, гуляя по городу, молодые люди рассказывают о себе. Разуверившаяся в чувствах человека, которого любит, Настенька обещает влюбленному в нее Мечтателю выйти за него замуж, но… появляется тот, другой, Настенька снова счастлива, а Мечтатель опять одинок.",
 "f-wd1982098": "Крым накануне полного освобождения от белогвардейцев. Возвращаясь из дозора, четвёрка отважных «неуловимых» подбивает аэроплан. В полевой сумке взятого в плен лётчика они обнаруживают секретное донесение, где говорится о существовании оборонительных укреплений вокруг приморского города, который красным ещё предстоит взять. Юные герои получают задание добыть карту укреплений и едут в город...",
 "f-wd3230416": "Это рассказ о трех днях из жизни бывшей военной летчицы, а ныне директора ПТУ Надежды Петрухиной. Она, уважаемый в городе человек, депутат горсовета, переживает тяжелый душевный кризис. По натуре Петрухина максималист. Война для таких, как она, стала одним из высших проявлений человеческого духа. Поэтому героиня и вспоминает войну с ужасом и вместе с тем как свой звездный час. Она, на ее беду, так и не смогла перестроиться и теперь со своим максимализмом и жертвенностью выглядит порой неуместно, а то и нелепо.",
 "f-wd7212768": "Действие фильма происходит в 1941 году в СССР перед началом и в первые месяцы Великой Отечественной войны. В небольшой деревушке Красное совершает вынужденную посадку военный самолёт У-2. Командование не имеет возможности отбуксировать самолёт и решает выставить возле него часового. В войсковой части неподалёку от деревни Красное проходит службу рядовой Иван Чонкин. Неказистый и простодушный солдат, с внешностью, далёкой от образцового воина, отбывает воинскую обязанность в хозяйственном подразделении полка, занимаясь тем, что работает при кухне, развозя грузы на лошади. Именно его командование отряжает на пост возле самолёта в деревне Красное...",
 "f-wd1252050": "Действие исторической драмы происходит в 1942 году в оккупированной немцами Белоруссии. Путевого обходчика Сущеню ложно обвиняют в сотрудничестве с оккупантами. Два партизана приезжают на хутор к Сущене, чтобы совершить расправу. В надежде доказать свою невиновность Сущеня пытается сделать моральный выбор в аморальных обстоятельствах.",
 "f-wd281297": "В аэропорту одной из европейских стран убит связной между немецким военным преступником доктором Хаасом и западногерманской разведкой. В кармане убитого обнаружена шифровка о закупке сырья для массового производства газа RH - нового психохимического оружия, разработкой которого и занимается Хаас в секретной лаборатории под вывеской фармацевтического центра в одном из западных курортных городков. Делом Хааса занимается советский разведчик, полковник Константин Тимофеевич Ладейников. Он попадает в поле зрения западных спецслужб, но просит разрешения у руководства остаться в стране и продолжить работу.",
 "f-wd1194976": "Они погибли в 1944 году, их было всего восемнадцать человек — комсомольский взвод, остановивший колонну немецких танков. Трагическое и комедийное, героическое и лирическое сплелись на экране в необычную ткань повествования об отцах, навсегда оставшихся молодыми, и о детях, пришедших туда, где ровно тридцать лет назад приняли свой последний смертный бой самые родные для них люди…",
 "f-wd2635696": "Скромная колхозница Ася-хромоножка любит разгильдяя Степана. Несмотря на то, что парень не хочет жениться, она решается родить от него ребенка…",
 "f-wd3540517": "Живет в сибирском селе старый Ермолай Воеводин. Четыре сына у него да дочь. Но как по-разному сложились их судьбы. Подался в Москву старший — Игнат, стал выступать в цирке, демонстрируя недюжинную силу. Он доволен своей жизнью и своими рассказами сманивает в город брата Максима. Тот устраивается на стройку чернорабочим, но постоянно чувствует свое одиночество. В думах своих он не порывает с деревней, а возвратиться мешает гордость. Средний сын, Степан, — человек неуемного характера, подрался «за правду» и угодил в тюрьму. За три месяца до освобождения он совершает побег и возвращается в деревню, чтобы повидать родных, походить по земле и, как он говорит, набрать сил отбыть наказание. В деревне с отцом остаются только его любимец Василий да немая Верка. Тяжело переживает Ермолай распад семьи, страстно мечтает собрать всех сыновей под крышей своего дома, да только сбудется ли его мечта?",
 "f-wd2910960": "Действие происходит в конце XVI века, накануне «смутного времени». Главное действующее лицо этой исторической трагедии - русский царь Борис Годунов, взошедший на престол вслед за Иваном Грозным после трагических событий: смерти старшего сына Грозного Федора и гибели юного царевича Димитрия.",
 "f-wd4294237": "Исторический фильм о вторжении поляков на территорию Руси (1611), создании Мининым и Пожарским народного ополчения. Начало XVII века. Уже шестой год русская земля под игом интервенции. Осенью 1610 года польские паны в обманом захватили Кремль и пытались прорваться на север Руси.  Повсюду вспыхивали восстания, но хорошо вооруженные интервенты разбивали разрозненные крестьянские отряды. Освободительное движение возглавили нижегородский купец Кузьма и князь Дмитрий Пожарский.",
 "f-wd1964597": "Крокодил Гена выясняет, что Чебурашка не умеет читать и хочет устроить его в школу. Им неожиданно помогает старуха Шапокляк, которая устраивает срочное завершение ремонта школы к первому сентября. Крокодил Гена становится преподавателем по живой природе.",
 "f-wd2141856": "История о путешествии к южному морю семейной пары из далекого алтайского села. Супруги впервые в жизни едут в отпуск по выделенной профкомом путевке, да еще в отдельном купе! Дорожные приключения и ритм новой жизни увлекают их, но и среди красот южной природы не могут они забыть о родных местах и близких людях, которые ждут их возвращения.",
 "f-wd114437078": "Гэри Джонсон — одинокий университетский преподаватель философии и психологии живёт обычной скучной жизнью с двумя кошками. Гэри хорошо разбирается в электронике и однажды начинает помогать полицейским в установке и настройке прослушивающей аппаратуры. Перед началом очередной операции выясняется, что копа, который должен выдавать себя за наёмного убийцу, на 4 месяца отстраняют от работы из-за скандала с применением неоправданного насилия. В итоге, чтобы добыть доказательства и арестовать будущего заказчика убийства, Гэри приходится самому сыграть киллера. Всё проходит успешно, преступник арестован, а Гэри на постоянной основе начинает участвовать в спецоперациях, притворяясь крутым специалистом по устранению. На новом задании судьба сводит Гэри с очаровательной Мэдисон, которая желает убить ненавистного мужа.",
 "f-wd27703192": "Мир пожирает неизвестная эпидемия, но герой сумел найти островок безопасности для жены и ребенка — мужчина вывез семью подальше в лес, где в одиноко стоящем домике надеется переждать безумие, которое обрушилось на цивилизацию. Глава семейства вводит жесткие порядки и строжайшую дисциплину, что вселяет страх в его домочадцев, однако защищает от смертельных опасностей внешнего мира. Однажды на пороге дома появляются безобидные, казалось бы, гости, и хрупкой безопасности семьи приходит конец.",
 "f-wd114450800": "Нью-Йорк. Ограбление идет не по плану и Немо, занимающийся кражами произведений искусства, оказывается запертым в роскошном пентхаусе.",
 "f-wd2067859": "Артур Мерсо — француз, постоянно проживающий в Алжире, убивает на пляже араба. Его арестовывают и он предстаёт перед судом…",
 "f-wd956681": "Действие происходит в Южной Калифорнии. После смерти жены отец с двумя детьми переезжает за город, чтобы восстановить и вновь открыть старый зоопарк.",
 "f-wd115269607": "В элитной частной школе появляется новая учительница — загадочная Мисс Новак. По просьбе родителей мисс Новак прививает детям новые привычки питания, обучает их осознанному подходу в выборе рациона, рассказывает, как сокращать потребление и тем самым заботиться об окружающем мире. Последователи философии Мисс Новак образуют закрытый клуб Зеро — тайное сообщество, члены которого решают, что они могут в принципе отказаться от еды — и тем самым изменить мир. Постепенно родители и школьная администрация начинают понимать, что что-то не так — но смогут ли они остановить Клуб Зеро?",
 "f-wd111464581": "На семью в отдаленном фермерском доме нападает невидимый зверь, но с наступлением ночи отец начинает превращаться в нечто неузнаваемое.",
 "f-wd68681442": "Потерявший родителей священник едет в Китай, где случайно обретает способность превращаться в динозавра. Сперва он ужасается своим новым способностям, но вскоре проститутка убеждает его использовать их для борьбы с преступностью. И с ниндзя.",
 "f-wd12655879": "Некрасивую девочку Ингу все любят и, играя, всегда выбирают «красавицей». И это справедливо - она самая добрая и сияющая девочка в большой детской компании. И только один мальчик откровенно говорит ей, что она некрасива. Он поселился в доме недавно и, получив прозвище Немой, не желает признавать непонятные правила игры.",
 "f-wd56461564": "Когда Ён-ху был ребёнком, его отец, полицейский и очень религиозный человек, погиб при исполнении. С тех пор парень живёт, затаив на Бога обиду, не любит сближаться с людьми и предпочёл реализоваться в MMA. Однажды на ладони ударной правой руки Ён-ху проступает стигмат, и с тех пор по ночам его приходят мучить злые потусторонние сущности. Пытаясь разобраться в происходящем, парень встречает священника-экзорциста, с которым ему придется наладить отношения, чтобы вместе противостоять дьявольским силам.",
 "f-wd626483": "Вам никогда не приходила в голову мысль попасть внутрь компьютерной игры и стать её участником? До определенного момента Кевин Флинн тоже думал, что это возможно лишь в его воображении. Но, оказавшись в секретной лаборатории, разрабатывающей компьютерные программы, ему предоставляется возможность увидеть электронный мир изнутри и сразиться в жестокой схватке с самим хозяином виртуальной вселенной.",
 "f-wd63981637": "В Белогорье мир и спокойствие, зло побеждено. Рядом отец Илья Муромец, возлюбленная Василиса в предсвадебных заботах, ставшие друзьями Баба Яга и Водяной и маленькие радости из современного мира, чтоб обеспечить комфортную жизнь — благо Меч-Кладенец даёт возможность регулярно прорубать дыру между мирами и бегать за припасами. Но тоска по родному миру тяготит Ивана. А ещё больше его заботит неминуемое начало Богатырских игр — съезда всех витязей Белогорья, где добры молодцы будут показывать удаль и силу. Той самой Богатырской силушки в себе Иван не чувствует, и опозориться на глазах у отца и невесты ему совсем не хочется. Однако, когда в самый разгар состязаний пробуждается древнее зло и само существование волшебного мира оказывается под угрозой, Ивану приходится объединиться и со старыми друзьями, и с новыми недругами. Им предстоит отправиться в дальнее путешествие, за пределы известного мира, чтобы обнаружить истоки зла и вернуть мир в Белогорье.",
 "f-wd18822138": "В центре внимания сын Аполло Крида — первого серьёзного соперника Рокки Бальбоа на ринге, в последствие ставшего лучшим другом героя. Молодой человек не испытывает никакой страсти к боксу, впрочем, и его семья не желает видеть парня в ипостаси бойца. Тем не менее, талант отца в какой-то момент проявляется и в Криде-младшем, и юноша отправляется на поиски наставника, коим для него в итоге становится постаревший Рокки, тоже не слишком жаждущий возвращаться к старым делам. Даже в качестве тренера.",
 "f-wd7737199": "По сюжету динозавры не вымерли, а эволюционировали в разумных существ и живут и здравствуют на Земле. А вот люди остались на довольно примитивной стадии развития. Фильм расскажет историю дружбы динозавра и маленького мальчика.",
 "f-wd21644309": "Успешному сотруднику ДПС Пете Васютину уже давно пора заводить семью, а он живет с мамой, хозяйкой придорожного кафе. И невеста есть — королева бензоколонки, кассирша Оля. В тот самый день, когда Петя решает сделать Оле предложение, в его служебную машину врезается пьяная поп-звезда Алина Шёпот. Чтобы избежать наказания, Алина решает соблазнить Петю…",
 "f-wd45740018": "Югославия. 1999 год. Российская спецгруппа получает приказ взять под контроль аэродром Слатина в Косово и удерживать его до прихода подкрепления. Но этот стратегический объект крайне важен албанскому полевому командиру и натовским генералам. Группа вынуждена принять неравный бой с Подпольная милиция. К аэродрому устремляются российские миротворцы и силы НАТО. Мир вновь близок к большой войне. Но командиру спецгруппы Андрею Шаталову не до политики: в аэропорту среди заложников его любимая девушка Ясна…",
 "f-wd288645": "Базирующееся в Египте высокотехнологичное международное военное подразделение, известное как G.I. Joe, противостоит зловещей корпорации, руководимой знаменитым оружейным бароном.",
 "f-wd1758468": "У Пипца появились последователи, мстители в масках во главе которых стоит обезбашенный Полковник. К несчастью за ними начинает охотиться Кровавый Угар, и только Убивашка способна этому противостоять. Супергерои попытались стать обычными подростками — Дэйвом и Минди. Но в виду неопределенного будущего, они хотят создать команду супергероев. Минди в костюме убивашки ловят копы, после ареста, ей приходится забыть о геройском прошлом и попытаться жить как самый обычный ребенок. В результате чего Пипец лишается напарника и вступает в ряды команды «Справедливость Навсегда» под предводительством бывшего преступника по прозвищу Полковник Звездно-полосатый. А Кровавый Угар, первый в своем роде суперзлодей, собирает в свою очередь лигу злодеев, с целью мести Убивашке и Пипцу за смерть своего отца. Теперь ему придется вступить в схватку со всеми супергероями команды.",
 "f-wd15975899": "В поисках внезапного и таинственного наследства, Дэнни и его друзья оказываются в Хобб Спрингс, на заброшенном курорте в горах Западной Вирджинии. Вскоре Дэнни узнает, что его родственники, которых он никогда не знал, вели довольно странный образ жизни, основывающийся на каннибализме. Дэнни придется выбирать между друзьями и родственниками.",
 "f-wd1658610": "Защитник Руси, богатырь Илья Муромец по навету бояр попадает в княжеское подземелье. Но когда на родную землю вновь приходит беда, вынужден князь идти на поклон Муромцу и друзьям его - Алеше Поповичу и Добрыне Никитичу…",
 "f-wd2381788": "В древнем русском городе Ростове родился в поповской семье сын. Назвали его родители Алёшей. А когда он вырос и стал богатырём, то совершил такие подвиги, что стал героем русских былин Алёшей Поповичем. Только подвиги его начались с конфуза... Подступила к Ростову тугарская вражеская орда во главе с Тугарином Змеем и потребовала, чтобы жители города выплатили дань. Поповский сын предложил план действий. Народ этот план одобрил и собрал гору золота. Алёша же умудрился собственный план «благополучно» провалить, да с каким треском! И золото упустил, и полгорода разрушил. После чего поклялся — Тугарина Змея изловить и золото вернуть. Отправился Алёша Попович в путь вместе с дедом Тихоном, который мальчика вырастил и воспитал, а чуть позже компанию им составили говорящий конь Юлий, купленный у цыган, почти 16-летняя красавица Любава, её бабка и их ослик Моисей...",
 "f-wd31827235": "На этот раз Лёша, Слава, Камиль и Саша едут в Питер. За один день наши герои побеждают немцев, хоронят дядю Борю, переживают за Михаила Прохорова, поют песню из любимого мультфильма и неожиданно для себя вспоминают слово «дендрологический», соглашаются с проводницей поезда «Адлер-Мурманск», что Месси лучше, чем Роналду, и выясняют, как правильно вести себя с деньгами, чтобы они на тебя не обиделись.",
 "f-wd27957869": "После исчезновения исследовательской подлодки группа спасателей отправляется в глубины Тихого океана, чтобы спасти экипаж. Опытный спасатель-подводник Джонас Тейлор присоединяется к опасной экспедиции и вскоре сталкивается с невероятной угрозой - гигантской доисторической акулой мегалодоном, которую считали вымершей миллионы лет. Теперь команде предстоит не только выжить в смертельно опасных водах, но и остановить древнего хищника, прежде чем он доберётся до поверхности и превратит побережье в место настоящего кошмара.",
 "f-wd27178": "Внезапно умирает король Дании. Его вдова, Гертруда, спешно вступает в брак с братом покойного мужа Клавдием, которого провозглашают новым королем. Принцу Гамлету является призрак и сообщает, что он предательски отравлен собственным братом.\r В поначалу застенчивом и мечтательном юноше зреет жажда мести и ненависть к убийце отца, и жалость к обманутой матери, идущей на поводу у собственных чувств. В свою очередь, Клавдий также хочет смерти пасынка.",
 "f-wd669592": "Техасский фермер Бик Бенедикт отправляется в Мэрилэнд за призовым жеребцом. Там он встречает женщину своей мечты Лесли и женится на ней. Молодая пара возвращается на свое ранчо, где Лесли предстоит приспособиться к жизни в изменившихся условиях.  Новая хозяйка ранчо разбивает сердце Джетта Ринка, нефтяного магната. Разгорается, и без того острое, соперничество между двумя техасскими семьями.",
 "f-wd136625": "Когда злой дух Кромешник посягает на самое дорогое — детские мечты, Северянин, Ледяной Джек, Кролик, Зубная Фея и Песочный Человек впервые объединяются, чтобы создать команду Хранителей снов…",
 "f-wd196685": "Один из самых выдающихся мировых специалистов по системам безопасности соглашается на последнюю рисковую операцию: сбежать из суперсекретной высокотехнологичной тюрьмы, которую называют «Гробницей». Преданный Рэй Бреслин вынужден прибегнуть к помощи напарника - заключенного Эмиля Ротмайера, чтобы разработать отчаянный и практически неосуществимый план побега из самой защищенной тюрьмы в мире!",
 "f-wd392441": "1665 год, голландский город Дельфт. В дом художника Йоханнеса Вермеера приходит 16-летняя девушка Гриет, чтобы работать служанкой. Вскоре она обращает на себя внимание живописца, потому что, несмотря на свой юный возраст, Гриет тонко чувствует не только результат творчества, но и сам процесс, механизм создания полотен, которым суждено будет жить в веках. Однажды Вермеер обращается с просьбой к Гриет - позировать ему для новой картины...",
 "f-wd10384115": "Выдающийся исследователь в области изучения искусственного интеллекта доктор Уилл Кастер работает над созданием компьютера, который сможет собрать в себе все знания и опыт, накопленные человечеством. Достаточно спорные эксперименты, проводимые Уиллом, прославили его и в то же время сделали основной целью радикальной анти-технологической группировки. Экстремисты делают всё возможное, чтобы остановить учёного.\r Однако в своих попытках уничтожить Уилла они добиваются обратного и становятся невольными участниками становления его абсолютного превосходства. Для его жены Эвелин и лучшего друга Макса Вотерса, тоже учёных-исследователей, встаёт вопрос, должны ли они продолжать этот эксперимент. Их худшие опасения претворяются в жизнь, когда жажда знаний Уилла переходит в неконтролируемую жажду власти…",
 "f-wd94998134": "Вдохновившись самопожертвованием Супермена, Брюс Уэйн вновь обретает веру в человечество. Он заручается поддержкой новой союзницы Дианы Принс, чтобы сразиться с ещё более могущественным противником. Бэтмен и Чудо-женщина набирают команду сверхлюдей для борьбы с пробудившейся угрозой.",
 "f-wd597239": "Фильм рассказывает правдивую историю Джона Рида, радикального американского журналиста во время Первой Мировой Войны. Он встречается с замужней женщиной Луизой Бриант, которая бросает своего мужа ради него. После политических разногласий в США, они уезжают в Россию, в то время когда там идет октябрьская революция 1917 года. Они вдохновляются решимостью коммунистов и возвращаются в штаты, надеясь устроить такую же революцию.",
 "f-wd30939513": "Похититель с множественным расстройством личности и террорист-инвалид «Мистер Стекло» выходят на своих давних противников — травмированную девочку-подростка Кейси и стареющего супергероя Дэвида Данна.",
 "f-wd274895": "Занесенная снегом Французская глубинка. В Поместье собирается семья для встречи рождества. Но праздник не состоится. Хозяин дома убит. 8 женщин, близких хозяину дома начинают расследование.\r Каждая из них под подозрением. У каждой есть мотив для убийства. День расследования открывает многие семейные тайны, которые были под семью замками.",
 "f-wd2313918": "В таинственных глубинах Вселенной патрульный звездолёт «Пушкин» обнаруживает космический корабль неизвестной землянам конструкции. На корабле находят полностью разрушенную лабораторию по клонированию человекоподобных существ. Среди погибших инопланетян оказывается один выживший искусственный гуманоид — девушка Нийя. На Земле выясняется, что в мозг инопланетянки зашит пульт управления, призванный гарантировать точное выполнение «особой миссии». Он начинает действовать в тот момент, когда Нийа в составе земной экспедиции высаживается на своей родной планете Десса…",
 "f-wd395279": "1916 год. Россия в критическом положении, на престоле безвольный Николай II. Придворные предчувствовали крах самодержавия. «И вот во дворец вошел и, глумясь и издеваясь, стал шельмовать над Россией неграмотный мужик с сумасшедшими глазами» — так писал Алексей Толстой о «святом старце» Распутине, который приобрел неограниченную власть над царем, а впоследствии стал жертвой придворного заговора.",
 "f-wd4440845": "Две сестры давно живут на попечении дяди, который взял их из детского дома и искренне мечтает о счастливой жизни для каждой. Девушки часто следуют его советам, но это не приносит им счастья. Старшая сестра жертвует всем, чтобы младшая стала актрисой, — и лишь спустя годы понимает, что напрасно отказывалась от своей мечты и судьбы…",
 "f-wd4466948": "О судьбах двух талантливых врачей, которые вместе начинали интересную работу, но не довели её до конца. Найдя неплохие, спокойные должности, они изменили своему призванию. Впрочем, один из героев сумел понять, что совершил ошибку. Он резко меняет свою жизнь…",
 "f-wd17431067": "Филиппок, так прозвали героя картины друзья, был наделен от природы самой неромантической внешностью. Он носил очки, лицо было округло, наивно, чуть ли не глуповато. От него так и веяло добротой и светом, и был он крайне неприспособлен к практической жизни, но порядочен, скромен, честен. Он писал, и не потому, что мечтал о славе и богатстве, а потому что не мог, наверное, не писать. Филиппку повезло, он встретил женщину и полюбил ее, одну-единственную, на всю жизнь - Зиночку, вдову комиссара, воспитывающую сына Ваську. Зиночка взяла Филиппка к себе, надеясь \"сделать из него человека\". Чего только она ни предпринимала, чтобы помочь его карьере. Филиппок стал журналистом, но не об этом фильм. Картина о большой, редкой любви, без которой не было бы книги и не нужен был бы фильм. Филиппок любил Зиночку всю жизнь, хотя та увлекалась другими мужчинами и даже один раз бросила Филиппка. Ушла, так как устала с ним нянчиться. Слава Богу, Любовь победила, и Зиночка вернулась к Филиппку.",
 "f-wd124624585": "Надя выросла и стала фигуристкой. Она мечтает о «Кубке Льда», как когда-то мечтала ее мама. Горин возражает против спортивной карьеры дочери — он оберегает ее от любых трудностей и его можно понять: он потерял слишком много. На тайной тренировке Надя знакомится с молодым и дерзким хоккеистом из Москвы, и между ними вспыхивает первая любовь. Отец не верит в искренность чувств юноши и разлучает пару. Но препятствия только укрепляют настоящую любовь, а когда любишь — самый сказочный финал может стать реальностью.",
 "f-wd368109": "У Илая и Джоша родители погибли на том самом кукурузном поле. Обеспеченные люди Аманда и Уильям усыновили сирот. Так деревенские мальчики попали в город. Джош быстро адаптировался и завел себе друзей. А Илай сажает кукурузу на заброшенном фабричном дворе и произносит при этом странные заклинания. Постепенно сила культа растет, ему приносятся жертвы, а бывший школьный отщепенец Эли, становится общепризнанным авторитетом и пророком…",
 "f-wd117429496": "Что-то странное творится в тихом приграничном городке Хоуп-Харбор. Сначала обнаруживают изуродованные трупы коров, а затем и погибших жуткой смертью людей. По слухам, на местности завёлся тигр, и, пока группа охотников отправляется выслеживать хищника в лес, начальник полиции идёт по кровавому следу, не подозревая, что его городок оказался в эпицентре инопланетного вторжения.",
 "f-wd21062112": "Произошедшее 15 января 2009 года назовут «Чудом на Гудзоне». В тот день капитан рейса 1549 Чесли Салленбергер совершил аварийную посадку самолета A320 на холодные воды реки Гудзон в Нью-Йорке. При этом никто из находившихся на борту 155 человек не пострадал. Но, несмотря на все почести со стороны общественности и СМИ, было начато расследование, которое угрожало профессиональной репутации и многолетней карьере капитана Салли.",
 "f-wd642559": "Выпускнику школы Скотту Томасу нужна помощь в изучении немецкого языка, поэтому он знакомится с жителем Германии по имени Майк и начинает с ним дружескую переписку. Причём Скотт абсолютно уверен, что Майк — это парень, и делится с ним своими переживаниями и проблемами, которые возникают у него с девушкой. Но в конце концов Скотт узнаёт, что Майк, точнее Мике — это обворожительная блондинка, которой Скотт очень понравился. И теперь он сделает всё, чтобы увидеться с Мике, даже совершит путешествие по Европе.",
 "f-wd4444030": "Они живут на предельной скорости. Они - стритрейсеры, уличные гонщики. Для них гонки - смысл жизни. Страсть, способная объединить самых разных людей. Даже таких, как Степан и Докер. Оба не только любят автомобили - они не мыслят жизни без скорости и риска. Но для одного цель никогда не оправдает средств, а для другого определяющее значение имеет лишь размер гонорара. Когда появляется дело «на миллион долларов» - организовать в один вечер угон дорогостоящих элитных автомобилей, - Докер понимает, что без заклятого друга ему не обойтись. Когда Катя, любимая девушка Докера, уходит к Степану, становится понятным, что конфликта не избежать...",
 "f-wd112430183": "2898 год. На Земле правит император, которому противостоят повстанцы из тайного города Шамбала. Правая рука императора, коммандер Манас, работает над проектом по поиску формулы бессмертия императора. С помощью повстанцев из проекта удается сбежать необычной девушке, которую за огромное вознаграждение пытаются поймать наемники императора. Тем временем древнее пророчество, гласящее, что явится спаситель и избавит человечество от страданий, начинает сбываться.",
 "f-wd126595889": "Барбер жаждет мести после ограбления его дома, уклончиво сообщая полиции, что его «Лакшми» похищена, но не уточнив, что это - человек или предмет. Он стремится вернуть неуловимую «Лакшми».",
 "f-wd130269576": "Чтобы исполнить мечту дочери и оплатить её обучение в балетной школе, Хэппи Гилмор решает вернуться в большой гольф. Вскоре ему вновь предстоит встретиться на поле со своим главным соперником — Шутером МакГевином.",
 "f-wd125637377": "Помощник тренера по баскетболу Гульшан Арора считает, что прекрасно разбирается в игре, и ему самое место на месте главного тренера. Однажды во время матча он вздорит с главным тренером, напивается, садится за руль и врезается в патрульную машину. Судья приговаривает его к 90 дням общественных работ — теперь Гульшан должен подготовить баскетбольную команду центра для людей с особенностями интеллектуального развития к участию в Международном Чемпионате в Мумбаи...",
 "f-wd124848369": "Заместитель директора Агентства по борьбе с финансовыми преступлениями Мэрибет Медина узнаёт о смерти своего бывшего руководителя Рэя Кинга. Пытаясь найти убийц, она использует подсказку Рэя и связывается с Кристианом Вольфом — гениальным математиком-аутистом и теневым аудитором с навыками киллера. Заручившись поддержкой своего брата Брэкстона, Кристиан постепенно собирает воедино все части головоломки, но и убийцы Кинга не дремлют.",
 "f-wd124260479": "Молодой инженер-робототехник Ариан Агнихотри, который, к огорчению родителей, не торопится заводить семью, перебирается из Индии в Соединенные Штаты, чтобы работать в компании своей тети Урмилы Шуклы. Там мужчина влюбляется в красивую девушку по имени Сифра, изначально не подозревая, что она является новейшей разработкой в области робототехники, почти не отличимой от живого человека. Уже не способный что-либо поделать со своими сильными чувствами, Ариан готов жениться на роботе, что приводит к череде комичных ситуаций.",
 "f-wd123207136": "\"Тангалаан\" - это необычное сочетание истории, мистики и социальной драмы; тем самым выгодно выделяется на фоне типичных индийских боевиков. Действие фильма разворачивается в конце XIX века, и перед нами - трагическая история племени, угнетаемого и местными властями и землевладельцами, и британскими колонизаторами. Главный герой, Тангалаан (Викрам), - вождь этого небольшого племени, потерявший землю и вынужденный работать на жестокого землевладельца, но мечтающий о свободе. Когда ему предлагают пойти с англичанином Клермонтом в поисках золота, он видит в этом шанс изменить не только свою судьбу, но и судьбу всего своего племени.",
 "f-wd80155482": "История жизни индийского футбольного тренера Сайед Абдул Рахима.",
 "f-wd113455828": "Фильм повествует о не простой любви простого солдата индийской армии и непростой девушки в Кашмире в 1964 году.",
 "f-wd130284195": "После свадьбы Апарна переезжает в дом Аджаяна, где он живет с престарелым отцом. Хотя ей известно трагическое прошлое Аджаяна - потеря жены из-за рака и пропавший сын, Апарна постепенно вливается в их жизнь рядом с заповедным лесом. Со временем она начинает задаваться вопросом, не скрывает ли дикая природа, окружающая их дом, глубокие семейные тайны.",
 "f-wd58411644": "В сентябре 2016 года вооруженные лица напали на индийскую военную базу в городке Ури, расположенном около линии границы, разделяющей индийский штат Джамму и Кашмир и самопровозглашенное государство Азад Кашмир под фактическим контролем Пакистана. В результате атаки погибло 19 и ранено 30 индийских солдат. Также было ликвидировано четверо нападавших. Всем казалось, что причастные к атаке смогут избежать возмездия. Мало кто мог предположить, что индийская армия вычислит виновных и спланирует уникальную в своём роде спецоперацию…",
 "f-wd262487": "Опытный ныряльщик Сагаар Сингх работает на человека, пытающего уговорить его пуститься на поиски давно затонувших сокровищ. В это же время младший брат Сагаара попадает в неприятности, бежит из Бангкока и возвращается к брату на Багамы в поисках убежища. Но убежать не так просто. 50 миллионов долларов или твоя жизнь. К тому же в наше время никому нельзя доверять. Ведь не все на самом деле так, как оно есть в действительности. И не все люди такие, какими они кажутся.",
 "f-wd108392396": "Рокки - громкий и яркий пенджабец, а Рани - интеллектуальная бенгальская журналистка. Они - полные противоположности друг другу, но влюбились с первого взгляда. Перед свадьбой герои решают пожить в течение трех месяцев с семьями друг друга, чтобы проверить свои чувства и понять, стоит ли им вступать в брак.",
 "f-wd136673072": "Фильм рассказывает о короткой, но яркой жизни офицера Аруна Кетапала, павшего в битве при Басантаре в ходе индо-пакистанской войны 1971 года. Параллельно разворачивается история его отца, который спустя 30 лет отправляется в Пакистан, чтобы пройти по следам сына. Картина соткана из воспоминаний: военные будни, юношеская любовь и последний бой с превосходящими силами противника. Прошлое и настоящее сходятся воедино, чтобы сохранить память о подвиге.",
 "f-wd771754": "Сын Заминдара Нарайяна Мукхерджи — Девдас вырос в мире, где богатство ценилось больше человеческой жизни. Его другом детства стала красивая девочка Паро и они весело жили в живописной деревне Тадж Сонапур. Казалось, весь мир существует только для двух детей, но семена страсти уже были посеяны…",
 "f-wd45273": "История о Ранвире Сингхе, который намерен найти убийцу своей любимой Сонии. Бизнесмен в депрессии жаждет мести. Он идет по горячим следам убийцы, чтобы отомстить. Для этого он отправляется в Турцию, чтобы попросить помощи у известного мафиози Армана Малика. Он управляет «подземным миром» вместе с прекрасной леди — Еленой, в то время, как его невеста Омиша не знает о его темных делах. Любитель жевать фрукты — инспектор KD, также является частью истории, и на этот раз его напарницу играет Амиша Патель. Действия разворачиваются в Турции и обещают быть непредсказуемыми.",
 "f-wd1801544": "Вирен впервые приезжает в Индию в свое поместье и там знакомиться с молодой и красивой соседкой Паллави. Вирен влюбляется в нее, но у девушки уже есть жених, за которого она и выходит замуж. Счастье их было недолгим, муж погибает. Умирает и Паллави, дав жизнь дочери. В память о своей любви Вирен, живущий в Лондоне, становится опекуном девочки. Их встреча происходит лишь через много лет, и оказывается, что девушка Пуджа как две капли воды похожа на свою мать... По иронии судьбы Пуджа влюбляется в своего опекуна. Вирен бежит от этой любви, но проделки Пуджи, ее молодость и преданность покоряют сердце Вирена.",
 "f-wd19804229": "Эта история — о путешествиях по лабиринтам времени. На сей раз проводником по времени будет не кабина, не машина, а обыкновенные часы. Часы с циферблатом на 24 часа, которые изготовил доктор Сетхураман. Мог ли добрый ученый предвидеть, что его черная тень — брат Атрейя — возмечтает стать Богом и в поисках чудодейственного механизма попытается уничтожить всю его семью? Но удача отвернулась от злодея, и на много лет он впал в кому, а маленький сын Сетху избежал гибели. Лишь 26 лет спустя он откроет тайну часов и лицом к лицу столкнется с убийцей своих родителей.",
 "f-wd1587154": "Мили танцует в группе, но это не было ее мечтой. Ее мечта снятся в настоящем кино. Видимо судьба услышала ее и сделала ей подарок. Однажды танцуя на берегу моря, она и не заметила, что за ней наблюдает известный актер Раджкамал. Он устраивает так, что Мили будут снимать в кино. Кроме того, сам Раджкамал не равнодушен к красивой танцовщице. Теперь все складывается в жизни Мили так как она мечтала: съемки в кино, в ухажерах известный актер, но… Но все равно ей чего-то не хватает, она грустит. Наверное, тоска в ее сердце появляется от того, что в ее душе до сих пор живут чувства к весельчаку Мунне.",
 "f-wd1873709": "«Шанс на удачу» — история двух мечтателей, Викрама и Соны, приехавших покорять индийскую фабрику грез. Они молоды, честолюбивы и талантливы. И у каждого из них своя дорога к желанной вершине. Сона довольно быстро находит продюсера, который соглашается устроить ей громкий дебют, а в ожидании этого счастливого события снимается в эпизодических ролях. Викрам рассчитывает только на себя и активно старается оказаться в нужном месте в нужное время. Кому же из них улыбнется удача?",
 "f-wd905399": "Бизнес отца Аамира находится в столь плачевном состоянии, что он отказывается расставаться даже с копейкой. Для него деньги - это все, что существует на свете. Ради них он готов пожертвовать даже своих честным именем. Когда он узнает о решении сына жениться на дочери миллионера, он мгновенно соглашается с сыном. Он даже идет на обман, когда преувеличивает размеры своего бизнеса в разговоре с отцом невесты. Но отец невесты разгадывает замысел своего будущего родственника и при всей публике позорит отца Аамира и своего будущего тестя. В свою очередь отец жениха не дает своего согласия на свадьбу и тем самым рушит надежды молодых влюбленных сердец на счастливую жизнь.",
 "f-wd187863": "Он посвятил его своей любимой актрисе Мадхури Диксит. Она сыграла в фильме в четырех ролях: в образе Шакунталы, героини одноименной драмы Калидаса, в образе Моны Лизы с картины Леонардо да Винчи, танцовщицы Сангиты и фотомодели Моники, в которую влюбляется молодой фотокорреспондент Шахрукх. Очарованный красотой Моники, он предлагает ей сфотографироваться на обложку модного журнала...",
 "f-wd1060820": "Сильный дождь застал проститутку Чамели и мужчину Амана врасплох. Всю ночь они проводят вместе… разговаривая. Эта ночь сближает их настолько, что на следующий день они стремятся встретиться снова. Вместе с героем Рахула Босе зритель проходит непростой путь от пустой жизни, где в прошлом лишь боль, а будущее не предвещает ничего хорошего, к пониманию самого себя и обретению чего-то хорошего и светлого.",
 "f-wd2486250": "Простой честный парень Махеш попадает в непростую ситуацию, в результате которой он становится в один ряд с преступниками. Более того Махеш даже получает кличку – Мунна. Другая героиня фильма тоже зарабатывает себе на жизнь не совсем честным путем, но она вынуждена это делать. На это девушка решилась после самоубийства матери. Каждый из этих героев оказался в сложной жизненной ситуации, но, не смотря ни на что, каждый из них продолжает бороться за свое счастье, за свою мечту.",
 "f-wd4225691": "После свадьбы счастливые молодожены Радж и Прия отправляются в свадебное путешествие в Швейцарию, где знакомятся с Викрамом и Сонией - другой семейной парой. Викрам уговаривает Раджа провести неделю на экзотическом острове Маврикий. Вскоре они становятся близкими друзьями. И вот однажды Викрам предлагает Раджу всего на одну ночь поменяться женами.",
 "f-wd18128126": "Действие происходит в древнем городе под названием Мохенджо Даро, который когда-то располагался на полуострове Индостан. В центре повествования — несколько жителей этого удивительного города, которые на фоне исторических событий сталкиваются с самыми обычными человеческими проблемами: влюбляются, ссорятся, расстаются, женятся…",
 "f-wd174454": "Аман пишет и издает стихи под псевдонимом Сагар. Об этом не знает даже его лучший друг Акаш. Все обнаруживается, когда Пуджа, девушка, в которую влюблен Акаш, признается ему, что полюбила Сагара за его прекрасные стихи. Аман готов пожертвовать своими чувствами ради дружбы. Но примет ли эту жертву Акаш?",
 "f-wd3417323": "Защищая честь своей любимой жены Сонии, Сунил случайно убивает ее обидчика. Суд приговаривает его к длительному тюремному заключению, но обстоятельства позволяют ему сбежать. Скрываясь от правосудия, он находит приют в доме красивой девушки Чандни и ее отца. Для всех Сунил становится мужем Чандни и дает свое имя ее незаконнорожденной дочери. Через пять лет судьба вновь сводит вместе Сунила и Сонию, которая одна воспитывает их с Сунилом сына. Однако рука закона вновь настигает Сунила",
 "f-wd508365": "Молодой человек ради денег по страховому полису пытается покончить жизнь самоубийством, но его спасают рыбаки и принимают за глухонемого миллионера. Комедия получает очередной виток развития, когда он встречает по-настоящему глухонемую девушку и влюбляется в нее.",
 "f-wd542866": "В основе сценария «Макбул» лежит шекспировская трагедия «Макбет», сюжет которой перенесен в современный Бомбей..",
 "f-wd6935310": "Убит молодой офицер полиции Арья, который еще недавно расправился с террористами и стал национальным героем. Расследование поручают его близкому другу, Энтони, которому удается докопаться до правды и найти виновного. Но в тот момент, когда он звонит своему начальнику Фархану сказать об этом, он попадает в аварию. Врачи констатируют потерю памяти, в то время как пресса, общественность, начальство требуют в кратчайшие сроки раскрыть дело. Фархан скрывает проблемы со здоровьем Энтони ото всех, веря, что только он сможет раскрыть дело еще раз. Не зная ничего ни о людях вокруг, ни о себе, у него есть лишь материалы дела и уверенность его начальника, что он сможет..",
 "f-wd65065643": "История Викрама Батры — офицера индийской армии, прославившегося своими подвигами во время Каргильской войны.",
 "f-wd980677": "Муннабхай опять влюбился, но на этот раз, чтобы завоевать сердце девушки, ему придется узнать как можно больше о Махатме Ганди. Эти знания очень сильно его меняют, и он в свою очередь хочет изменить и всех вокруг.",
 "f-wd849343": "Двадцать лет тому назад Балдев Синг эмигрирует в Англию и оседает в Лондоне вместе с семьёй. Но даже после столь продолжительного проживания на чужбине он сохраняет приверженность национальным традициям и планирует выдать замуж старшую дочь Симран за сына старого друга, живущего в Пенджабе. Незадолго перед помолвкой Симран знакомится с весельчаком и балагуром Раджом.  Симран очень симпатичен Радж, но она далеко не сразу осознаёт, что под маской беззаботности скрывается преданная и любящая её душа. Когда молодые люди наконец-то понимают, что любят друг друга, уже поздно, приготовления к помолвке невозможно остановить. Единственная возможность избежать непоправимого — бежать, но Радж убежден, что им в жизни не будет счастья без благословения родителей Симран…",
 "f-wd573743": "Признанный мастер кунг-фу Ип Ман живёт в Фошане — городе, славном школами боевых искусств. Ип Ман практикует вин-чун и, хотя является сильнейшим бойцом города, своей школы у него нет, и он не берет учеников. Дома он проводит лишь легкие спарринги с приятелями. Проходят годы, Китай захватывают воинственные японцы, и Ип Ман оказывается одним из немногих, кто даже в жесточайших условиях оккупации не забывает о чести, достоинстве и, конечно же, мудрости, которую несет в себе кунг-фу.",
 "f-wd395411": "Александрия Египетская. Начало V века нашей эры. Великая жизнь, страстная любовь и трагическая гибель прекрасной Гипатии, первой в истории женщины-ученого — философа, математика, астронома. Перед ее мыслью преклонялись мудрецы, на ее лекции стекались тысячи, она предвосхитила открытия Галилея и Коперника, к ее слову прислушивались правители, красота ее ума и тела разбивала сердца.",
 "f-wd28114432": "Молодого бизнесмена Адриана Дориа обвиняют в убийстве любовницы, и он решает воспользоваться услугами Вирджинии Гудман, лучшего в стране специалиста по выходу из самых сложных ситуаций. Адриан содержится под домашним арестом, а завтра состоится судебное заседание, поэтому вечером к нему приходит Вирджиния, чтобы придумать наилучшую стратегию защиты. Для неё это последнее дело, и она не собирается его проигрывать.",
 "f-wd1076605": "XVI век. В Японии идет гражданская война. Бедный горшечник получает шанс как следует подзаработать — его горшки на удивление хорошо продаются, и изумленный ремесленник крепко держит в кулаке невиданные доселе серебряные монеты. Заработок вызывает азарт, быстро переходящий в одержимость.",
 "f-wd391143": "Главный герой истории - работающий по всему миру охотник за сокровищами Джей Си по кличке «Азиатский ястреб». Известный антиквар предлагает ему отыскать шесть редких статуэток в виде голов животных. В свое время эти бронзовые скульптуры входили в набор из 12-ти предметов, олицетворявших знаки зодиака. Фигурки украшали фонтан легендарного Летнего дворца на окраине Пекина. В 1860 году величественное сооружение было разграблено и разрушено англо-французскими войсками на исходе Второй опиумной войны, а статуэтки безвозвратно утеряны.",
 "f-wd1634355": "Это рассказ и о больном мальчике, мечтающем стать водителем трамваев, который каждый день заходит в невидимый трамвай, поворачивает сотни невидимых рычажков, поправляет несуществующую фуражку и бежит с криком, имитирующим стук трамвайных колёс: «До-дес-ка-ден». О двух пьяницах, которые в подпитии обменялись собственными жёнами. О человеке, который из-за измены любимой жены отрешается от мира, уходит на дно и даже чуткая забота раскаявшейся супруги не может вернуть его к миру.\r Хромой клерк устраивает вечеринку для сослуживцев, но веселье оканчивается дракой. Толстяк, воспитывает шестерых детей неверной жены. Безумный архитектор, рассказывает сыну о своих прекрасных градостроительных замыслах, а по вечерам собирает вместе с ним объедки, которыми однажды мальчик и отравится…",
 "f-wd572522": "Группа малолетних преступников ведет жестокую жизнь в печально известных трущобах Мехико; среди них - юный Педро, чья нравственность постепенно разлагается и разрушается остальными.",
 "f-wd2005033": "Военный врач Кёдзи во время операции заражается сифилисом от своего пациента Наката. Оба не начинают лечение вовремя, и болезнь круто меняет жизни не только самих Кёдзи и Накаты, но и их близких…",
 "f-wd660874": "Фильм посвящен теме памяти об атомной бомбардировке Нагасаки и тому, как для современного человека, не затронутого трагедией лично, вообще возможно аутентично выстраивать свое отношение к этому событию и говорить о нем, в том числе через разницу между поколениями и нациями.",
 "f-wd1404323": "Однажды рано утром Маркос, который обманывает каждого, включая своих родных сестру Валерию и брата Федерико, замечает Хуана — ребяческого и приятного мошенника, когда тот успешно осуществлял изменение счета на кассе.  Хуана поймали, так как он пытался проделать это же самое жульничество и на следующем счете. Маркос вступает в разговор, представившись полицейским, и выводит Хуана из магазина.  Но как только они оказываются на улице, коварный Маркос открывает себя совсем с другой стороны, он оказывается жуликом, но с игрой намного более высоких ставок.  Объяснив Хуану, что не может работать без напарника (предыдущий пропал неделю назад), Маркос приглашает его стать своим партнером по преступлениям, которого он давно искал, и предлагает давать ему уроки по проведению преступлений.  Хуан принимает предложение, потому что он очень нуждается в деньгах. Но они договариваются о сотрудничестве пока только на один день — попробовать.",
 "f-wd150881": "Ана, восьмилетняя девочка, живущая в Мадриде с бабушкой и двумя сестрами, оплакивает смерть своей матери.",
 "f-wd1273736": "Как выяснилось, Годзилла, убитый кислородом-разрушителем, был не единственным своем роде. Вскоре появляется еще один Годзилла, которого на этот раз называют Гигантисом. Гигантис появляется вместе с другим монстром — Ангирусом. Гигинатис и Ангирус появляются в Осаке, где начинают сражение. После долгой и упорной борьбы Гигантис убивает Ангируса и продолжает крушить город. Вскоре люди придумывают план, как избавиться от монстра…",
 "f-wd2355570": "Несколько человек пробуют использовать в своих интересах наивность маленькой девочки, чтобы взять деньги, которые ее мама дала ей, чтобы купить золотую рыбку.",
 "f-wd13218260": "Одержимый мечтой об успешной карьере архитектор Рёта, его молодая жена и 6-летний сын кажутся идеальной семьей. Но герой теряет все жизненные ориентиры в тот день, когда узнает, что в роддоме, где родился его сын, подменили двух младенцев. Мальчик, которого Рёта с женой воспитывали, им не родной, а их собственный ребенок растет в семье со скромным достатком.",
 "f-wd1518701": "После нападения на рыбацкую лодку единственный выживший член экипажа понимает, что это не кто иной, как воскресший Годзилла. Однако попытки предать эту историю огласке подавляются японским правительством на фоне растущей политической напряженности между Соединенными Штатами и Советским Союзом, которые готовы бомбить Японию, чтобы остановить монстра.",
 "f-wd343667": "Секретный завод по производству наркотиков разрушает экологию маленького озера. Владелица озера, красавица Лао, возбуждает судебный процесс против наркомафии.  Талантливый адвокат Джонни Лан, по приказу коррумпированных властей, должен отстаивать в суде интересы мафии. Адвокат с помощью друзей начинает тайное расследование деятельности мафии.",
 "f-wd1077309": "Глория встречает Франциско, человека, чья социальная внешность выдает его истинное «я», спрятанное под ней.",
 "f-wd87192572": "Тщеславный миллиардер задался целью вписать свое имя в историю, взявшись за создание идеального фильма. Сценарий — книга Нобелевского лауреата, режиссер — модная и эксцентричная, в главных ролях — разбитной секс-символ кумир миллионов и высоколобый драматический актер. Ждать шедевра или ждать беды?",
 "f-wd1312929": "Католический священник отец Анхель с помощью библии вычисляет день, когда на земле родится Антихрист. Он знает дату, но не знает место, поэтому пускается во все тяжкие, чтобы сам Дьявол подписал с ним контракт о покупке души. Помощниками святому отцу становятся случайный знакомый из магазина тяжелой музыки и популярный ведущий оккультной телепередачи.",
 "f-wd690651": "Бьерне и Свен – два приятеля, работающие в мясном магазине. У Свена большие амбиции: слишком долго он подчинялся другим людям. Бьерне же равнодушен ко всему. Лишь девушка по имени Астрид занимает его внимание. Чтобы избавиться от своего злобного хозяина Хольгера, друзья открывают собственную мясную лавку. Их дела идут неважно до тех пор, пока Свену не приходит в голову идея приготовить новое мясное блюдо, мысль хорошая, но где они достанут необходимые продукты…",
 "f-wd94943": "Анжелика, необыкновенно красивая бедная аристократка вынуждена выйти замуж за Жоффрея де Пейрака. Несмотря на его внешность она со временем полюбила его. Влюбленные живут счастливо в своем замке, пока однажды к ним не приезжает король. Восхищенный красотой Анжелики Людовик XIV хочет сделать ее своей наложницей…",
 "f-wd108919489": "Городская пара переезжает в небольшую деревню в поисках спокойной жизни в гармонии с природой. Однако им придется столкнуться с жестокостью и недружелюбием местных жителей, что приведет к непредотвратимым последствиям...",
 "f-wd1066749": "37-летний Тору слышит в гамбургском аэропорту мелодию песни Beatles «Norwegian Wood» и переносится мыслями в свою юность — в 60-е годы, когда он был токийским студентом тяжело переживавшим смерть своего лучшего друга, совершившего самоубийство…",
 "f-wd1190796": "Действие этой захватывающей психологической драмы происходит в Киото в 1865 году. Содзабуро, 18-летний юноша, изящный и стройный, как девушка, поступает в отряд самураев императора. Он не знает женской любви. Юноша Содзабуро бесстрашен, блестяще владеет мечом, и его принимают в самурайский \"эскадрон смерти\" Синсенгуми. Содзабуро ещё не знает, что для самурая любовь и смерть всегда неразделимы.  Между Содзабуро Кано и его соперником, хитрым Ташизо, жаждущим главенствующей роли самурая, растёт напряжённость. Противостояние этих двоих повлияет на остальных персонажей, раскрыв давно подавленные эмоции...",
 "f-wd301823": "Случилось так, что самый обыкновенный паренёк, работающий на автозаправке, столкнулся с самым обыкновенным, но от этого ничуть не менее отвратительным бандитом из «Якудзы», решившим помыть свою машину.Существует важное правило выживания в Японии: категорически запрещается вступать в конфронтацию с настоящим гангстером, какое бы настроение у тебя не было. К несчастью, герой фильма, Масаки, забыл об этом правиле. Роковая встреча на бензоколонке изменила жизни двух людей навсегда. Масаки пришлось очень хорошо узнать, что такое оружие, кровь и смерть…",
 "f-wd2280159": "Если бы Сатана искал местечко для филиала ада на Земле, ему не пришлось бы долго возиться. Наверняка им стала бы тюрьма Карандиру, самое жуткое исправительное заведение в Бразилии.  Фантастическая антисанитария, отвратительная еда, охранники-садисты и нарушения всех мыслимых прав человека сделали ее печально знаменитой задолго до того, как однажды в 1992 году доведенные до отчаяния заключенные Карандиру подняли мятеж.  Полиция с огромным трудом потопила восстание в крови, убив 111 человек. В итоге, из-за разразившегося международного скандала властям пришлось разрушить тюрьму до основания как символ национального позора.",
 "f-wd13229518": "Патагония, 1960 г. По дороге в Бариоче немецкий физик встречает аргентинское семейство. Там, на берегу озера Нагуэль Хуапи, Ева, Энцо и трое их детей собираются сдавать меблированную комнату. Образцовая семья вновь пробуждает в ученом тоску по чистоте и совершенству. Его внимание особенно привлекает 12-летняя Лилит, которая кажется слишком маленькой для своего возраста. Не догадываясь о том, кем на самом деле является их новый знакомый, семья соглашается приютить его. Обаяние этого человека, его элегантные манеры, знания и богатство очаровывают их… но однажды они понимают, что живут рядом с одним из величайших преступников всех времен.",
 "f-wd485677": "Это история пациентки психиатрической больницы, которая внезапно решила, что она не человек, а киборг, а рис ей есть не нужно — питается она от батареек. Но пациент из соседней палаты влюблен в нее, и он знает, что должен спасти ее, убедив в том, что она человек, а никакой не киборг.",
 "f-wd492288": "История этих двоих началась еще в университете, когда двадцатилетний студент Сын Мин влюбляется в свою сокурсницу Со Ён. Но парень не успел признаться в своих чувствах, из-за недоразумения они перестают общаться и расстаются… Прошло пятнадцать лет, и вот, однажды, к известному архитектору Сын Мину обращается Со Ён, для того, чтобы он помог восстановить ее старый дом. В то время как строительство дома продвигается, пара начинает снова влюбляться друг в друга",
 "f-wd671423": "Джо Навахо — единственный выживший в кровавой резне, устроенной в поселении бандой Дункана. В числе прочих жителей была и жена Джо. Он клянется отомстить за смерть любимой и вступает в схватку с Дунканом и его людьми.",
 "f-wd2413683": "«Очень испанское кино» — фильм-пародия режиссёра Хавьера Руиса Кальдеры и сценариста Пако Кабесаса. Несмотря на то, что фильм снимался в Испании и на испанском языке, его оригинальным названием является английское «Spanish Movie»",
 "f-wd715374": "Пять лет подряд каждое утро 18-летний Такуми развозил тофу, гоняя по горным дорогам на папиной старенькой Тойоте. Жизнь его однообразна, друзья не блещут интеллектом. Но работа заставила его стать настоящим профи в крутых виражах на повороте.  И вот случайно ему предлагают поучаствовать в знаменитом нелегальном состязании «Давид и Голиаф» на своей скромненькой на вид Тойоте АЕ86 против Профессиональных ночных гонщиков.  Блестящая, но неожиданная победа над местной звездой Такеши будоражит скрытый в нем до этого дух соревнования, а внезапная слава неизбежно ведет к бесчисленным приключениям, и каждое из них становится все рискованнее и увлекательнее предыдущего…",
 "f-wd1946689": "Действие происходит в вымышленном городе Маллепа. Иммигранты разных рас и национальностей смешиваются, каждый занимается своим бизнесом. Тут мы встречаем Кэя, вампира, который потерял волю к жизни после отъезда его единственного друга-вампира. Кэй хочет умереть, но вскоре его встречает сирота - парень по имени Сё. Сё узнает о вампиризме Кэя и не пугается этого. Постепенно он становится его лучшим другом. Действие переносится на несколько лет вперед, когда его банда подростков стала взрослой. Они грабят местную мафию, действуя так бесстрашно, как будто ничего не может им повредить, хотя на самом деле единственным бессмертным среди них является Кэй. Затем, в ходе одного «дела», они встречают Сона, и их судьбы переплетаются навсегда",
 "f-wd2461978": "История семьи, в поисках лучшей жизни переехавшей из Токио в провинцию. Двое братьев-школьников сначала становятся объектом насмешек и издевок, но постепенно добиваются уважения.",
 "f-wd21218461": "Находясь в машине вместе со своими детьми, управляющий банка получает анонимный телефонный звонок. Незнакомый голос сообщает ему, что у него есть всего несколько часов, на то, чтобы найти большую сумму денег, иначе бомба под его сиденьем взорвется…",
 "f-wd376117": "Вдова Оцунэ в одиночку воспитывает сына. Денег в семье не было и нет, поэтому отправить растущего мальчика в школу женщина не в состоянии. Наслушавшись рассказов местного учителя о том, что «нет образования — нет и будущего», Оцунэ решает все же отдать сына учиться. Жизнь стареющей швеи превращается в бесконечный акт самопожертвования.",
 "f-wd1073800": "История Роберто, одинокого владельца хозяйственной лавки, погруженного в свой собственный мир; его жизнь разделилась на «до» и «после» более 20 лет назад... Дни, дела и привычки нашего героя расписаны поминутно; любое нарушение годами устоявшегося порядка и представлений о сути вещей будет критичным... Все бы так и продолжалось, но внезапное вмешательство судьбы нарушило монотонное существование, а аргентинца и китайца свела вместе корова, упавшая с неба...",
 "f-wd1661151": "Кинорежиссёр и его малолетний сын Пуя отправляются в поездку на машине по стране, чтобы найти прежних друзей, которые могли остаться в живых после землетрясения 1990 года в Гилане.",
 "f-wd1517788": "Ринго возвращается с гражданской войны, неожиданно он узнает, что какие-то мексиканцы напали на его дом и убили его родственников. Его жена и дочь находятся в плену у мексиканцев. Ринго переодевается в мексиканского пеона и начинает планировать свою месть",
 "f-wd2856158": "1987 год, Севилья. Группа 7 специальный отряд полиции с особо важным заданием: очистить город от проституции и наркотрафика, положив конец разъедающей все силе, которая захватила улицы. Во главе отряда стоят Анхель, молодой офицер, стремящийся стать детективом, и Рафаэль, жестокий и надменный, но очень эффективный опытный коп.  Основной метод действия группы 7 — в борьбе с преступностью самим обходить закон с помощью насилия, угроз, полуправды и лжи. Для них все средства хороши.  По мере того как они продвигаются в своей миссии вперед, два офицера становятся на разные пути. Анхель оказывается увлеченным своими амбициями, а Рафаэль неожиданно для самого себя привязывается и влюбляется в молодую красавицу Лючию, которую перед этим подбирает на улице.",
 "f-wd519893": "Главы крупнейших мировых держав вынуждены забыть о разногласиях и объединиться, чтобы дать отпор оккупировавшим Землю инопланетным захватчикам. Для начала нужно разрушить ближайшую базу пришельцев, расположенную на Луне.",
 "f-wd568518": "Антуан взрослеет, и уже не тот бунтарь, каким он был раньше. Его любви к Колетт посвящается это психологическое исследование юности.",
 "f-wd1808194": "В недалеком будущем планета Земля подвергается нашествию инопланетных захватчиков. Чудом выжившей горстке людей понадобится помощь суперагента, обладающего сверхъестественными возможностями и способного совершать путешествия во времени. Быстрый ум, мгновенная реакция и прекрасная физическая форма делают его непобедимым. Но теперь перед ним стоит самая сложная и опасная задача - вернуться в прошлое и изменить исход битвы за будущее Земли..."
};
